const redactActions = `-- name: RedactActions :execrows
UPDATE action
SET payload = '{}'::jsonb, result = NULL,
    payload_hash = encode(sha256(convert_to(action_type || E'\n{}', 'UTF8')), 'hex'),
    redacted_by_action_id = $1::uuid
WHERE id = ANY($2::uuid[]) AND redacted_by_action_id IS NULL
`

type RedactActionsParams struct {
	ByActionID uuid.UUID
	Ids        []uuid.UUID
}

// Empties actions about an assignment deleted for good, naming the deletion:
// who did what, when, on what and with what outcome stay; what they were
// given and returned go, and their hash is an empty call's.
func (q *Queries) RedactActions(ctx context.Context, arg RedactActionsParams) (int64, error) {
	result, err := q.db.Exec(ctx, redactActions, arg.ByActionID, arg.Ids)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const redactTotalsLine = `-- name: RedactTotalsLine :execrows
UPDATE grade g
SET breakdown = jsonb_set(g.breakdown, '{items}', (
        SELECT jsonb_agg(CASE WHEN x.item->>'id' = $1::uuid::text
                              THEN jsonb_build_object('id', x.item->'id', 'kind', 'assignment', 'deleted', true)
                              ELSE x.item END ORDER BY x.n)
        FROM jsonb_array_elements(g.breakdown->'items') WITH ORDINALITY AS x(item, n)))
FROM grade_component c
WHERE c.id = g.component_id AND c.course_id = $2::uuid AND g.origin = 'computed'
  AND jsonb_typeof(g.breakdown->'items') = 'array'
  AND g.breakdown->'items' @> jsonb_build_array(jsonb_build_object('id', $1::uuid::text))
`

type RedactTotalsLineParams struct {
	AssignmentID uuid.UUID
	CourseID     uuid.UUID
}

// The line of a deleted assignment in the working of the course's totals
// that still name it, superseded ones: it says the assignment was deleted,
// and nothing of the grade it was. The total's number is kept: it is what
// the student was shown.
func (q *Queries) RedactTotalsLine(ctx context.Context, arg RedactTotalsLineParams) (int64, error) {
	result, err := q.db.Exec(ctx, redactTotalsLine, arg.AssignmentID, arg.CourseID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const renditionKeysOfDocuments = `-- name: RenditionKeysOfDocuments :many
SELECT r.storage_key::text AS storage_key
FROM file_rendition r
JOIN document_version_file f ON f.id = r.file_id
WHERE f.document_id = ANY($1::uuid[]) AND r.storage_key IS NOT NULL
ORDER BY r.storage_key
`

// The PDFs of the files of every version of the documents.
func (q *Queries) RenditionKeysOfDocuments(ctx context.Context, documentIds []uuid.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, renditionKeysOfDocuments, documentIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var storage_key string
		if err := rows.Scan(&storage_key); err != nil {
			return nil, err
		}
		items = append(items, storage_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const shareDocumentInCourse = `-- name: ShareDocumentInCourse :one
SELECT id, kind, purged_at FROM document WHERE id = $1 AND course_id = $2 FOR KEY SHARE
`

type ShareDocumentInCourseParams struct {
	ID       uuid.UUID
	CourseID uuid.UUID
}

type ShareDocumentInCourseRow struct {
	ID       uuid.UUID
	Kind     string
	PurgedAt *time.Time
}

// A document an assignment is about to name as its instructions or rubric,
// held FOR KEY SHARE until the assignment is written: a purge, which locks
// it FOR UPDATE, waits, or is waited for and seen.
func (q *Queries) ShareDocumentInCourse(ctx context.Context, arg ShareDocumentInCourseParams) (ShareDocumentInCourseRow, error) {
	row := q.db.QueryRow(ctx, shareDocumentInCourse, arg.ID, arg.CourseID)
	var i ShareDocumentInCourseRow
	err := row.Scan(&i.ID, &i.Kind, &i.PurgedAt)
	return i, err
}
